#include "effects.h"
#ifndef EF_MUTANT
#define EF_MUTANT 0
#endif
enum ef_status ef_checksum(const unsigned char*p,size_t n,uint32_t*out){if(!out||(!p&&n)||n>32)return EF_INVALID;uint32_t value=0;for(size_t i=0;i<n;++i)value+=p[i];*out=value;return EF_OK;}
enum ef_status ef_cached(struct ef_cache*c,const unsigned char*p,size_t n,uint32_t*out){if(!c||!out||(!p&&n)||n>32||!c->generation||!c->allocator.take||!c->allocator.release)return EF_INVALID;if(c->borrows)return EF_BUSY;if(c->failed&&c->permanent)return EF_FAILED;if(!c->scratch){unsigned char*storage=c->allocator.take(c->allocator.context,32);if(!storage){c->failed=1;return EF_NOMEM;}c->scratch=storage;c->failed=0;}for(size_t i=0;i<n;++i)c->scratch[i]=p[i];return ef_checksum(c->scratch,n,out);}
enum ef_status ef_cache_reset(struct ef_cache*c){if(!c||!c->generation||!c->allocator.release)return EF_INVALID;if(EF_MUTANT!=1&&c->borrows)return EF_BUSY;if(c->generation==UINT32_MAX)return EF_FULL;if(c->scratch)c->allocator.release(c->allocator.context,c->scratch);c->scratch=0;c->failed=0;++c->generation;return EF_OK;}
enum ef_status ef_cache_borrow(struct ef_cache*c,const unsigned char**out){if(!c||!out||!c->scratch)return EF_INVALID;if(c->borrows==UINT32_MAX)return EF_FULL;++c->borrows;*out=c->scratch;return EF_OK;}
enum ef_status ef_cache_return(struct ef_cache*c){if(!c||!c->borrows)return EF_INVALID;--c->borrows;return EF_OK;}
enum ef_status ef_pool_take(struct ef_pool*p,unsigned char**out){if(!p||!out)return EF_INVALID;if(p->requests==UINT32_MAX)return EF_FULL;++p->requests;for(unsigned i=0;i<16;++i)if(!(p->used&(1u<<i))){p->used|=1u<<i;*out=&p->bytes[i];return EF_OK;}return EF_FULL;}
enum ef_status ef_pool_return(struct ef_pool*p,unsigned index){if(!p||index>=16||!(p->used&(1u<<index)))return EF_INVALID;p->used&=~(1u<<index);return EF_OK;}
enum ef_status ef_parse(struct ef_parser*p,const unsigned char*data,size_t n,struct ef_view*out){if(!p||!out||!p->generation||(!data&&n)||n>32)return EF_INVALID;if(EF_MUTANT!=2&&p->borrowed)return EF_BUSY;if(p->cursor>SIZE_MAX-n)return EF_FULL;for(size_t i=0;i<n;++i){unsigned char c=data[i];p->scratch[i]=c>='a'&&c<='z'?(unsigned char)(c-'a'+'A'):c;}p->cursor+=n;p->borrowed=1;out->owner=p;out->generation=p->generation;out->length=n;out->data=p->scratch;return EF_OK;}
enum ef_status ef_view_release(struct ef_view*v){if(!v||!v->owner||!v->owner->borrowed||v->generation!=v->owner->generation)return EF_INVALID;v->owner->borrowed=0;v->owner=0;v->data=0;v->length=0;return EF_OK;}
enum ef_status ef_parser_reset(struct ef_parser*p,uint32_t seed){if(!p||!p->generation)return EF_INVALID;if(p->borrowed)return EF_BUSY;if(p->generation==UINT32_MAX)return EF_FULL;p->cursor=0;p->seed=seed;++p->generation;for(unsigned i=0;i<32;++i)p->scratch[i]=0;return EF_OK;}
uint32_t ef_random(struct ef_parser*p){p->seed=p->seed*1664525u+1013904223u;return p->seed;}
enum ef_status ef_attempt(ef_callback_fn f,void*ctx,unsigned nonblocking,unsigned attempts,unsigned*used){if(!f||!used||attempts>16||!nonblocking)return EF_INVALID;unsigned char buffer[16];*used=0;while(*used<attempts){int s=f(ctx,buffer,sizeof buffer);++*used;if(s>0)return EF_OK;if(s<0)return EF_FAILED;}return EF_INCOMPLETE;}
enum ef_status ef_sort(int*a,size_t n){if((!a&&n)||n>16)return EF_INVALID;for(size_t i=1;i<n;++i){int value=a[i];size_t j=i;while(j&&a[j-1]>value){a[j]=a[j-1];--j;}a[j]=value;}return EF_OK;}
static void copy(struct ef_record*a,const struct ef_record*b){a->key=b->key;a->identity=b->identity;for(unsigned i=0;i<32;++i)a->payload[i]=b->payload[i];}
enum ef_status ef_sort_records(struct ef_record*a,size_t n){if((!a&&n)||n>16)return EF_INVALID;for(size_t i=1;i<n;++i){struct ef_record value;copy(&value,&a[i]);size_t j=i;while(j&&(EF_MUTANT==3?a[j-1].key>=value.key:a[j-1].key>value.key)){copy(&a[j],&a[j-1]);--j;}copy(&a[j],&value);}return EF_OK;}
